def load_parts(rows):
    valid = []
    errors = []
    for index, row in enumerate(rows, start=1):
        try:
            missing = [key for key in ("name", "length", "width", "quantity") if key not in row]
            if missing:
                raise ValueError("缺少字段")
            valid.append({
                "name": str(row["name"]),
                "total": float(row["length"]) * float(row["width"]) * int(row["quantity"]),
            })
        except (ValueError, TypeError):
            errors.append(index)
    return valid, errors

