#include <stdio.h>

typedef struct { double length, width, height; } Part;

double part_area(const Part *p) {
    if (p == NULL) {
        return 0.0;
    }
    double lw = p->length * p->width;
    double wh = p->width * p->height;
    double lh = p->length * p->height;
    return 2.0 * (lw + wh + lh);
}

int main(void) {
    setbuf(stdout, NULL);
    Part p = {30, 20, 10};
    printf("%.1f\n", part_area(&p));
    return 0;
}

