#include <stdio.h>
#include <stdlib.h>

static int balance = 0;

void *take(size_t n) { void *p = malloc(n); if (p) balance++; return p; }
void give(void *p) { if (p) { free(p); balance--; } }

int main(void) {
    void *a = take(8), *b = take(8);
    printf("分配 2 块：%d\n", balance);
    give(a); printf("释放 1 块：%d\n", balance);
    give(b); printf("全部释放：%d\n", balance);
    return 0;
}

