#include <stdio.h>

#define SENTINEL 0x5A5A
#define CAPACITY 4

typedef struct { int guard_head; int slot[CAPACITY]; int guard_tail; } GuardedInts;

int guarded_set(GuardedInts *g, int index, int value) {
    if (index < 0 || index > CAPACITY) return -1;
    g->slot[index] = value;
    return 0;
}

int guarded_ok(const GuardedInts *g) {
    return g->guard_head == SENTINEL && g->guard_tail == SENTINEL;
}

int main(void) {
    setbuf(stdout, NULL);
    GuardedInts g;
    g.guard_head = SENTINEL;
    g.guard_tail = SENTINEL;
    g.slot[0] = g.slot[1] = g.slot[2] = g.slot[3] = 0;
    printf("写入 index=4 返回：%d\n", guarded_set(&g, 4, 99));
    printf("哨兵完好：%s\n", guarded_ok(&g) ? "是" : "否");
    return 0;
}

