#include <stdio.h>

int safe_sum(const int *a, int n, int *out) {
    if (a == NULL || out == NULL) return -1;
    if (n <= 0) return -2;
    int i;
    int total = 0;
    for (i = 0; i < n; i++) {
        total += a[i];
    }
    *out = total;
    return 0;
}

int main(void) {
    setbuf(stdout, NULL);
    int arr[3] = {1, 2, 3};
    int out = 0;
    printf("%d\n", safe_sum(arr, 3, &out));
    return 0;
}
